using Core.Domain.Entities;
using Microsoft.EntityFrameworkCore;

namespace Core.Infrastructure.Persistence;

/// <summary>
/// Idempotent seed for ISO reference data: all 249 ISO 3166-1 countries, ISO 3166-2
/// subdivisions for the major countries, their capital/major cities, and ISO 4217
/// currencies with their native symbols. Safe to call on every startup - each set is
/// only inserted when its table is empty.
/// </summary>
public static class GeoReferenceSeed
{
    public static async Task SeedAsync(CoreDbContext db)
    {
        // Currencies
        if (!await db.Currencies.AnyAsync())
        {
            db.Currencies.AddRange(GetCurrencies());
            await db.SaveChangesAsync();
        }

        // Countries
        if (!await db.Countries.AnyAsync())
        {
            var currencyMap = await db.Currencies
                .ToDictionaryAsync(c => c.Code, c => c.Id);

            var countries = GetCountries().ToList();
            foreach (var country in countries)
            {
                if (country.CurrencyCode is not null &&
                    currencyMap.TryGetValue(country.CurrencyCode, out var currId))
                {
                    country.DefaultCurrencyId = currId;
                }

                if (country.Code.Length == 2)
                    country.FlagEmoji = GetFlagEmoji(country.Code);
            }

            db.Countries.AddRange(countries);
            await db.SaveChangesAsync();
        }

        // Subdivisions
        if (!await db.Subdivisions.AnyAsync())
        {
            db.Subdivisions.AddRange(GetSubdivisions());
            await db.SaveChangesAsync();
        }

        // Cities
        if (!await db.Cities.AnyAsync())
        {
            db.Cities.AddRange(GetCities());
            await db.SaveChangesAsync();
        }

        // Translations
        if (!await db.CountryTranslations.AnyAsync())
        {
            await SeedTranslationsAsync(db);
        }
    }

